const e = $('TRG - Receber Dados WF004').first().json;

// ==============================
// SERVIÇOS
// ==============================
const servicos = $items('GS - Buscar Serviço')
  .map(i => i.json)
  .filter(x => x && x.ID_SERVICO);

// Normaliza textos para comparação flexível
const normalizar = (texto) => {
  const stopwords = new Set([
    'em', 'de', 'da', 'do', 'das', 'dos',
    'para', 'com', 'no', 'na'
  ]);

  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter(p => !stopwords.has(p))
    .join(' ')
    .trim();
};

const servicoSolicitado = normalizar(e.servico);

let s = null;

// 1. Correspondência exata após normalização
if (servicoSolicitado) {
  s = servicos.find(x =>
    normalizar(x.NOME) === servicoSolicitado
  );
}

// 2. Correspondência parcial
if (!s && servicoSolicitado) {
  s = servicos.find(x => {
    const nome = normalizar(x.NOME);

    return (
      nome.includes(servicoSolicitado) ||
      servicoSolicitado.includes(nome)
    );
  });
}

if (!s || !s.ID_SERVICO) {
  return [{
    json: {
      ...e,
      status: 'SERVICO_NAO_ENCONTRADO',
      horarios: [],
      resposta_cliente:
        'Não encontrei esse serviço no nosso catálogo. Pode confirmar o nome do serviço desejado?'
    }
  }];
}


// ==============================
// PROFISSIONAIS
// ==============================
const profs = $items('GS - Buscar Profissional')
  .map(i => i.json)
  .filter(x => x && x.ID_PROFISSIONAL);

let p = null;

if (e.id_profissional) {
  p = profs.find(
    x => String(x.ID_PROFISSIONAL) === String(e.id_profissional)
  );
}

if (!p && e.profissional) {
  const alvo = normalizar(e.profissional);

  p = profs.find(
    x => normalizar(x.NOME) === alvo
  );
}

// fallback: primeiro profissional ativo
if (!p) {
  p = profs[0] || null;
}

if (!p) {
  return [{
    json: {
      ...e,
      id_servico: s.ID_SERVICO,
      servico: s.NOME,
      status: 'SEM_PROFISSIONAL',
      horarios: [],
      resposta_cliente:
        'Não encontrei profissionais disponíveis para este atendimento.'
    }
  }];
}


// ==============================
// DATA
// ==============================
const timezone = 'America/Sao_Paulo';
const textoData = String(e.data || '')
  .trim()
  .toLowerCase();

let dataRef;

if (textoData === 'hoje') {

  dataRef = DateTime
    .now()
    .setZone(timezone)
    .startOf('day');

} else if (
  textoData === 'amanhã' ||
  textoData === 'amanha'
) {

  dataRef = DateTime
    .now()
    .setZone(timezone)
    .plus({ days: 1 })
    .startOf('day');

} else {

  dataRef = DateTime.fromFormat(
    String(e.data || ''),
    'dd/MM/yyyy',
    { zone: timezone }
  );

  if (!dataRef.isValid) {
    dataRef = DateTime.fromFormat(
      String(e.data || ''),
      'yyyy-MM-dd',
      { zone: timezone }
    );
  }

  if (!dataRef.isValid) {
    dataRef = DateTime.fromISO(
      String(e.data || ''),
      { zone: timezone }
    );
  }
}

if (!dataRef || !dataRef.isValid) {

  return [{
    json: {
      ...e,
      id_servico: s.ID_SERVICO,
      servico: s.NOME,
      id_profissional: p.ID_PROFISSIONAL,
      profissional: p.NOME,
      status: 'DATA_INVALIDA',
      horarios: [],
      resposta_cliente:
        'Não entendi a data informada. Pode confirmar a data desejada?'
    }
  }];
}


// ==============================
// DISPONIBILIDADE
// ==============================
const dsAll = $items('GS - Buscar Disponibilidade')
  .map(i => i.json)
  .filter(
    x =>
      x &&
      x.DIA_SEMANA_NUM !== undefined &&
      x.DIA_SEMANA_NUM !== ''
  );

const agAll = $items('GS - Buscar Agendamentos')
  .map(i => i.json)
  .filter(x => x && x.HORA_INICIO);

const eventos = $items('Get many events')
  .map(i => i.json)
  .filter(x => x && (x.start || x.id));


// Luxon:
// 1 = segunda ... 7 = domingo
// Cadastro:
// 0 = domingo ... 6 = sábado
const dia = dataRef.weekday % 7;

const ds = dsAll.filter(
  x =>
    String(x.ID_PROFISSIONAL) ===
    String(p.ID_PROFISSIONAL)
);

const ag = agAll.filter(
  x =>
    String(x.ID_PROFISSIONAL) ===
    String(p.ID_PROFISSIONAL)
);

const d = ds.find(
  x => Number(x.DIA_SEMANA_NUM) === dia
);

if (!d) {

  return [{
    json: {
      ...e,
      id_servico: s.ID_SERVICO,
      servico: s.NOME,
      duracao_min: Number(s.DURACAO_MIN || 60),
      valor: Number(s.VALOR || 0),
      id_profissional: p.ID_PROFISSIONAL,
      profissional: p.NOME,
      status: 'SEM_DISPONIBILIDADE',
      horarios: [],
      resposta_cliente:
        'Não encontrei disponibilidade cadastrada para este profissional nessa data.'
    }
  }];
}


// ==============================
// FUNÇÕES DE HORÁRIO
// ==============================
const tm = (t) => {
  const [h, m] = String(t || '00:00')
    .slice(0, 5)
    .split(':')
    .map(Number);

  return h * 60 + m;
};

const hs = (m) =>
  String(Math.floor(m / 60)).padStart(2, '0') +
  ':' +
  String(m % 60).padStart(2, '0');


// ==============================
// COMPARAÇÃO DE DATA
// ==============================
const mesmaData = (raw) => {

  if (!raw) return false;

  let dt = DateTime.fromFormat(
    String(raw),
    'dd/MM/yyyy',
    { zone: timezone }
  );

  if (!dt.isValid) {
    dt = DateTime.fromFormat(
      String(raw),
      'yyyy-MM-dd',
      { zone: timezone }
    );
  }

  if (!dt.isValid) {
    dt = DateTime.fromISO(
      String(raw),
      { zone: timezone }
    );
  }

  return (
    dt.isValid &&
    dt.hasSame(dataRef, 'day')
  );
};


// ==============================
// OCUPAÇÕES NO SHEETS
// ==============================
const occAgenda = ag
  .filter(
    a =>
      String(a.STATUS || '').toUpperCase() !== 'CANCELADO'
  )
  .filter(
    a => mesmaData(a.DATA)
  )
  .map(
    a => [
      tm(a.HORA_INICIO),
      tm(a.HORA_FIM)
    ]
  );


// ==============================
// OCUPAÇÕES GOOGLE CALENDAR
// ==============================
const occCalendar = eventos.map(ev => {

  if (
    ev.start &&
    ev.start.dateTime &&
    ev.end &&
    ev.end.dateTime
  ) {

    const inicio = DateTime
      .fromISO(ev.start.dateTime)
      .setZone(timezone);

    const fim = DateTime
      .fromISO(ev.end.dateTime)
      .setZone(timezone);

    if (
      inicio.isValid &&
      fim.isValid &&
      inicio.hasSame(dataRef, 'day')
    ) {

      return [
        tm(inicio.toFormat('HH:mm')),
        tm(fim.toFormat('HH:mm'))
      ];
    }

    return null;
  }

  // Evento de dia inteiro
  if (
    ev.start &&
    ev.start.date
  ) {

    const inicioDia = DateTime.fromISO(
      ev.start.date,
      { zone: timezone }
    );

    if (
      inicioDia.isValid &&
      inicioDia.hasSame(dataRef, 'day')
    ) {
      return [0, 24 * 60];
    }
  }

  return null;
})
.filter(Boolean);


const occ = [
  ...occAgenda,
  ...occCalendar
];


// ==============================
// DURAÇÃO / INTERVALO
// ==============================
const dur = Number(
  s.DURACAO_MIN || 60
);

const intervalo = Number(
  s.TEMPO_INTERVALO_MIN || 0
);


// ==============================
// JORNADA DO PROFISSIONAL
// ==============================
const ini = tm(d.HORA_INICIO);
const fim = tm(d.HORA_FIM);

const pi = d.INTERVALO_INICIO
  ? tm(d.INTERVALO_INICIO)
  : null;

const pf = d.INTERVALO_FIM
  ? tm(d.INTERVALO_FIM)
  : null;


// ==============================
// FILTRO POR PERÍODO
// ==============================
const periodoFiltro = normalizar(
  e.periodo
);

const dentroPeriodo = (mins) => {

  if (periodoFiltro === 'manha') {
    return mins < 12 * 60;
  }

  if (periodoFiltro === 'tarde') {
    return (
      mins >= 12 * 60 &&
      mins < 18 * 60
    );
  }

  if (periodoFiltro === 'noite') {
    return mins >= 18 * 60;
  }

  return true;
};


// ==============================
// HORÁRIO MÍNIMO SOLICITADO
// ==============================
const horaMin = e.hora_inicio
  ? tm(String(e.hora_inicio).slice(0, 5))
  : null;


// ==============================
// GERAR HORÁRIOS LIVRES
// ==============================
const horarios = [];

for (
  let x = ini;
  x + dur <= fim;
  x += 30
) {

  const fimServico = x + dur;

  const fimComIntervalo =
    fimServico + intervalo;

  // intervalo/almoço
  if (
    pi !== null &&
    pf !== null &&
    x < pf &&
    fimComIntervalo > pi
  ) {
    continue;
  }

  // conflito de agenda
  if (
    occ.some(
      ([a, b]) =>
        x < b &&
        fimComIntervalo > a
    )
  ) {
    continue;
  }

  // período solicitado
  if (!dentroPeriodo(x)) {
    continue;
  }

  // horário mínimo solicitado
  if (
    horaMin !== null &&
    x < horaMin
  ) {
    continue;
  }

  horarios.push(
    hs(x)
  );
}


// ==============================
// RESPOSTA FINAL
// ==============================
const dataFormatada =
  dataRef.toFormat('dd/MM/yyyy');

let respostaCliente;

if (horarios.length) {

  respostaCliente =
    `Encontrei horários disponíveis para ${s.NOME} ` +
    `em ${dataFormatada}: ` +
    `${horarios.slice(0, 6).join(', ')}.`;

} else {

  respostaCliente =
    `Não encontrei horários livres para ${s.NOME} ` +
    `em ${dataFormatada} com os critérios informados.`;
}


return [{
  json: {
    ...e,

    status:
      horarios.length
        ? 'OK'
        : 'SEM_HORARIOS',

    id_servico:
      s.ID_SERVICO,

    servico:
      s.NOME,

    duracao_min:
      dur,

    valor:
      Number(s.VALOR || 0),

    id_profissional:
      p.ID_PROFISSIONAL,

    profissional:
      p.NOME,

    data:
      dataFormatada,

    horarios,

    resposta_cliente:
      respostaCliente
  }
}];
